package com.hbm.weapon.b92;
import com.hbm.entity.LegacyTrackingRange;import com.hbm.explosion.ExplosionNuclearExempt;import net.minecraft.core.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.nbt.*;import net.minecraft.network.syncher.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.util.Mth;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;import net.minecraft.world.phys.shapes.CollisionContext;
/** Exact oldEntity projectile, not a modern Arrow surrogate: cached-block delayed detonation and repeat entity-hit blasts remain. */
public final class EntityB92Beam extends Entity implements LegacyTrackingRange,ExplosionNuclearExempt {
 private static final EntityDataAccessor<Byte> FLAGS=SynchedEntityData.defineId(EntityB92Beam.class,EntityDataSerializers.BYTE);
 private int xTile=-1,yTile=-1,zTile=-1,inData,ticksInGround,ticksInAir;private Block inTile=Blocks.AIR;private boolean inGround,hasCachedBlock,legacyDefaultSize;private double damage=2;public double gravity;public int canBePickedUp,arrowShake;public Entity shootingEntity;
 public EntityB92Beam(EntityType<? extends EntityB92Beam> type,Level level){super(type,level);}
 public EntityB92Beam(Level level){this(B92Content.BEAM.get(),level);}
 public EntityB92Beam(Level level,double x,double y,double z){this(level);setPos(x,y,z);}
 public EntityB92Beam(Level level,LivingEntity shooter,float velocity){this(level);shootingEntity=shooter;moveTo(shooter.getX(),shooter.getY()+shooter.getEyeHeight(),shooter.getZ(),shooter.getYRot(),shooter.getXRot());setPos(getX()-Mth.cos(getYRot()/180F*(float)Math.PI)*.16F,getY()-.10000000149011612D,getZ()-Mth.sin(getYRot()/180F*(float)Math.PI)*.16F);setThrowableHeading(-Mth.sin(getYRot()/180F*(float)Math.PI)*Mth.cos(getXRot()/180F*(float)Math.PI),-Mth.sin(getXRot()/180F*(float)Math.PI),Mth.cos(getYRot()/180F*(float)Math.PI)*Mth.cos(getXRot()/180F*(float)Math.PI),velocity*1.5F,1);}
 public EntityB92Beam(Level level,LivingEntity shooter,LivingEntity target,float velocity,float inaccuracy){this(level);legacyDefaultSize=true;refreshDimensions();shootingEntity=shooter;if(shooter instanceof Player)canBePickedUp=1;setPosRaw(getX(),shooter.getY()+shooter.getEyeHeight()-.10000000149011612D,getZ());double dx=target.getX()-shooter.getX(),dy=target.getBoundingBox().minY+target.getBbHeight()/3F-getY(),dz=target.getZ()-shooter.getZ();double horizontal=sqrt(dx*dx+dz*dz);if(horizontal>=1.0E-7){float yaw=(float)(Math.atan2(dz,dx)*180/Math.PI)-90,pitch=(float)-(Math.atan2(dy,horizontal)*180/Math.PI);moveTo(shooter.getX()+dx/horizontal,getY(),shooter.getZ()+dz/horizontal,yaw,pitch);setThrowableHeading(dx,dy+(float)horizontal*.2F,dz,velocity,inaccuracy);}}
 public EntityB92Beam(Level level,int x,int y,int z,double mx,double my,double mz,double grav){this(level);legacyDefaultSize=true;refreshDimensions();setPosRaw(x+.5F,y+.5F,z+.5F);setDeltaMovement(mx,my,mz);gravity=grav;}
 @Override public EntityDimensions getDimensions(Pose pose){return legacyDefaultSize?EntityDimensions.scalable(.6F,1.8F):super.getDimensions(pose);}
 @Override protected void defineSynchedData(SynchedEntityData.Builder builder){builder.define(FLAGS,(byte)0);}
 @Override public int legacyTrackingRange(){return 1000;}
 @Override public boolean shouldRenderAtSqrDistance(double distance){double size=getBoundingBox().getSize();if(Double.isNaN(size))size=1;size*=640;return distance<size*size;}
 private static float sqrt(double value){return(float)Math.sqrt(value);}
 public void setThrowableHeading(double x,double y,double z,float velocity,float inaccuracy){float length=sqrt(x*x+y*y+z*z);x/=length;y/=length;z/=length;x+=random.nextGaussian()*(random.nextBoolean()?-1:1)*.002499999832361937D*inaccuracy;y+=random.nextGaussian()*(random.nextBoolean()?-1:1)*.002499999832361937D*inaccuracy;z+=random.nextGaussian()*(random.nextBoolean()?-1:1)*.002499999832361937D*inaccuracy;x*=velocity;y*=velocity;z*=velocity;setDeltaMovement(x,y,z);float horizontal=sqrt(x*x+z*z);yRotO=(float)(Math.atan2(x,z)*180/Math.PI);setYRot(yRotO);xRotO=(float)(Math.atan2(y,horizontal)*180/Math.PI);setXRot(xRotO);ticksInGround=0;}
 @Override public void lerpTo(double x,double y,double z,float yaw,float pitch,int steps){setPos(x,y,z);setRot(yaw,pitch);}
 @Override public void lerpMotion(double x,double y,double z){setDeltaMovement(x,y,z);if(xRotO==0&&yRotO==0){float horizontal=sqrt(x*x+z*z);yRotO=(float)(Math.atan2(x,z)*180/Math.PI);setYRot(yRotO);xRotO=(float)(Math.atan2(y,horizontal)*180/Math.PI);setXRot(xRotO);moveTo(getX(),getY(),getZ(),getYRot(),getXRot());ticksInGround=0;}}
 @Override public void tick(){
  super.tick();if(tickCount>100)discard();var motion=getDeltaMovement();if(xRotO==0&&yRotO==0){yRotO=(float)(Math.atan2(motion.x,motion.z)*180/Math.PI);setYRot(yRotO);}
  // In1.7 the unset sentinelY=-1 was guaranteed air. Do not read actual deepslate at(-1,-1,-1) in1.21.
  if(hasCachedBlock&&!level().getBlockState(new BlockPos(xTile,yTile,zTile)).isAir()){discard();explode();}
  if(arrowShake>0){arrowShake--;return;}
  ticksInAir++;Vec3 start=position(),end=position().add(motion);HitResult hit=level().clip(new ClipContext(start,end,ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,CollisionContext.of(this)));if(hit.getType()==HitResult.Type.MISS)hit=null;else end=hit.getLocation();
  Entity closest=null;double nearest=0;
  for(Entity candidate:level().getEntities(this,getBoundingBox().expandTowards(motion).inflate(1))){if(!candidate.isPickable()||candidate==shootingEntity&&ticksInAir<5)continue;var intercept=candidate.getBoundingBox().inflate(.3F).clip(start,end);if(intercept.isPresent()){double distance=sqrt(start.distanceToSqr(intercept.get()));if(distance<nearest||nearest==0){closest=candidate;nearest=distance;}}}
  if(closest!=null)hit=new EntityHitResult(closest);
  if(hit instanceof EntityHitResult victim&&victim.getEntity() instanceof Player player&&(player.getAbilities().invulnerable||shootingEntity instanceof Player shooter&&!shooter.canHarmPlayer(player)))hit=null;
  if(hit instanceof EntityHitResult){int unusedDamage=Mth.ceil(sqrt(motion.lengthSqr())*damage);if(getIsCritical())unusedDamage+=random.nextInt(unusedDamage/2+2);explode();}
  else if(hit instanceof BlockHitResult block){var pos=block.getBlockPos();xTile=pos.getX();yTile=pos.getY();zTile=pos.getZ();hasCachedBlock=true;var state=level().getBlockState(pos);inTile=state.getBlock();inData=state.getValues().entrySet().stream().filter(entry->entry.getKey().getName().equals("legacy_meta")&&entry.getValue() instanceof Integer).mapToInt(entry->(Integer)entry.getValue()).findFirst().orElse(0);}
  setPosRaw(getX()+motion.x,getY()+motion.y,getZ()+motion.z);setYRot((float)(Math.atan2(motion.x,motion.z)*180/Math.PI));if(isInWater()){discard();explode();}if(isInWaterRainOrBubble())clearFire();setPos(getX(),getY(),getZ());checkInsideBlocks();
 }
 private void explode(){B92Blast.explode(level(),getX(),getY(),getZ(),10);}
 @Override protected void addAdditionalSaveData(CompoundTag tag){tag.putInt("xTile",xTile);tag.putInt("yTile",yTile);tag.putInt("zTile",zTile);tag.putShort("life",(short)ticksInGround);tag.putString("inTile",BuiltInRegistries.BLOCK.getKey(inTile).toString());tag.putByte("inData",(byte)inData);tag.putByte("shake",(byte)arrowShake);tag.putByte("inGround",(byte)(inGround?1:0));tag.putByte("pickup",(byte)canBePickedUp);tag.putDouble("damage",damage);tag.putBoolean("hbmCachedHit",hasCachedBlock);}
 @Override protected void readAdditionalSaveData(CompoundTag tag){xTile=tag.getInt("xTile");yTile=tag.getInt("yTile");zTile=tag.getInt("zTile");ticksInGround=tag.getShort("life");var block=ResourceLocation.tryParse(tag.getString("inTile"));inTile=block==null?Blocks.AIR:BuiltInRegistries.BLOCK.get(block);inData=tag.getByte("inData")&255;arrowShake=tag.getByte("shake")&255;inGround=tag.getByte("inGround")==1;if(tag.contains("damage",Tag.TAG_ANY_NUMERIC))damage=tag.getDouble("damage");canBePickedUp=tag.contains("pickup",Tag.TAG_ANY_NUMERIC)?tag.getByte("pickup"):tag.getBoolean("player")?1:0;hasCachedBlock=tag.contains("hbmCachedHit")?tag.getBoolean("hbmCachedHit"):xTile!=-1||yTile!=-1||zTile!=-1;}
 @Override protected MovementEmission getMovementEmission(){return MovementEmission.NONE;}@Override public boolean isAttackable(){return false;}
 public void setDamage(double amount){damage=amount;}public double getDamage(){return damage;}public void setKnockbackStrength(int ignored){}
 public void setIsCritical(boolean critical){byte flags=entityData.get(FLAGS);entityData.set(FLAGS,(byte)(critical?flags|1:flags&-2));}public boolean getIsCritical(){return(entityData.get(FLAGS)&1)!=0;}
}
